</template>
<script>
import LeadDataService from "../../service/DataService";
import modalpricebook from '../../views/PurchaseOrder/ModalPriceBook.vue';
var ajaxRequestComplete = true;
export default {
    components: {
        modalpricebook
    },
    data() {
        return {
            FormSchema: [],
            quoteID: 0,
            reqFromId: 0,
            CountryData: [],
            Ischeckshipping: false,
            sameShippingAddressAsBilling: false,
            IsInventory: true,
            isTaxNameFilled: false,
            buttons: [{
                type: "submit",
                class: "btn btn-warning save",
                text: "<i class='fa fa-save pr-2'></i>Save As Draft",
                value: "D",
                isVisible: false,
                onClick: this.saveForm
            },
            {
                type: "submit",
                class: "btn btn-success save",
                isVisible: false,
                text: "<i class='fa fa-save pr-2'></i>Submit",
                onClick: this.saveForm
            },
            {
                type: "button",
                class: "btn btn-danger",
                isVisible: false,
                text: "<i class='fa fa-close pr-2'></i> Cancel",
                onClick: this.Close
            }
            ],
            dateformat: null,
            userId: null,
            companyId: null,
            isLoading: false,
            qlist: '',
            showPricebookModal: false,
            submited: false,
            statusId: 0,
            selectedQuotationType: '0',
            ProductSummary: null,
            RequisitionId: null,
            DefaultUserAddress: [],
            Address: {
                BillingAddress: {
                    BillingCompanyName: '',
                    BillingContactPerson: '',
                    BillingAccountAddress: '',
                    BillingAccountAddress2: '',
                    BillingAccountCity: '',
                    BillingCity: '',
                    BillingCityList: [],
                    BillingZipCode: '',
                    BillingZipCodeList: [],
                    BillingState: '',
                    BillingStateList: [],
                    BillingCompanyNameList: [],
                    BillingCountry: ''
                },
                ShippingAddress: {
                    ShippingCompanyName: '',
                    ShippingContactPerson: '',
                    ShippingAccountAddress: '',
                    ShippingAccountAddress2: '',
                    ShippingAccountCity: '',
                    ShippingCity: '',
                    ShippingCityList: [],
                    ShippingZipCode: '',
                    ShippingZipCodeList: [],
                    ShippingState: '',
                    ShippingStateList: [],
                    ShippingCompanyNameList: [],
                    ShippingCountry: ''
                }
            },
            AllUserAddresses: [],
            VendorData: [],
            fileMulitpleData: [],
            fileData: [],
            file: [],
            filePath: '',
            VendorsDetails: [],
            isOnlineVendor: false,
            ProductName: '',
            Quantity: 0,
            RequisitionLocationId: 0,
            IsManually: false,
            BillingAddressList: [],
            ShippingAddressList: []

        }
    },
    computed: {
        summaryTotal: function () {
            let total = 0;
            var data = this.ProductSummary.SummaryData;
            for (let i = 0; i < data.length; i++) {
                if (data[i].ProductRate > 0) {
                    total = parseFloat(total, 10) + parseFloat(data[i].ProductItemTotal, 10);
                }
            }
            total = parseFloat(total, 10).toFixed2();
            this.ProductSummary.SubTotal = total;
            if (this.ProductSummary.ShippingCharges > 0) {
                total = parseFloat(total, 10) + parseFloat(this.ProductSummary.ShippingCharges, 10);
            }
            if (this.ProductSummary.Adjustments > 0) {
                total = parseFloat(total, 10) - parseFloat(this.ProductSummary.Adjustments, 10);
            }
            total = parseFloat(total, 10).toFixed2();
            this.ProductSummary.SummaryTotal = total;
            return total;
        },
    },
    created: async function () {


        this.userId = this.GetUserInfo.ID;
        this.companyId = this.GetUserInfo.CompanyId;
        this.dateformat = this.GetUserInfo.DateFormat;
        this.currency = this.GetUserInfo.Currency;

        this.RequisitionId = parseInt(this.$route.params.AssetRequisitionId);
        this.quoteID = this.$route.params.OrderId == "0" ? 0 : this.$route.params.OrderId;

        if (this.currency) {
            this.currency = (this.currency == "(USD)" ? "$" : this.currency);
        }
        Number.prototype.toFixed2 = function () {
            var amount = Math.floor(parseFloat(this, 10) * 100) / 100;
            return parseFloat(amount, 10).toFixed(2);
        };

        await this.GetCountryData('', 'COUNTRIES');
        this.qlist = 0;

        this.UpdateRequisition(this.RequisitionId).then(() => {
            return this.FetchData();
        }).then(() => {
            return this.FetchDefaultUserAddress();
        });


    },
    methods: {
        onCancel: function () {
            if (this.reqFromId != "0") {
                this.$router.push({ path: `/CRM/ViewDealDetails/${this.reqFromId}/CRM/CRM_DEALS` });
            } else {
                this.$router.push({
                    path: `/AssetRequisition/ViewNewProductRequest/${this.RequisitionId}/ACT`
                });


                // this.$router.push(`/AssetRequisition/ViewNewProductRequest/${this.RequisitionId}`);

            }
        },
        clearRateIfNameEmpty: function (item, type, isInPercentage) {
            if ($.trim(item.TAX_NAME) == '') {
                item.TAX_RATE = 0;
                item.TAX_NAME = $.trim(item.TAX_NAME)
            } else {
                this.isTaxNameFilled = false;
            }
        },
        outside: function (e) {
        },
        onlyDecimal: function (item, type, isInPercentage) {
            if (type == 'TAX') {
                if (item.TAX_NAME != '') {
                    item.TAX_RATE = item.TAX_RATE.replace(/[^0-9.]/g, '').replace(/(\..*)\./g, '$1');
                    if (isInPercentage && parseFloat((item.TAX_RATE != '') ? item.TAX_RATE : 0) > 100) {
                        item.TAX_RATE = '100';
                    }
                } else {
                    this.isTaxNameFilled = true;
                    item.TAX_RATE = "0";
                }
            } else if (type == 'DISCOUNT') {
                item.ProductDiscountValue = item.ProductDiscountValue.replace(/[^0-9.]/g, '').replace(/(\..*)\./g, '$1');
                if (isInPercentage && parseFloat((item.ProductDiscountValue != '') ? item.ProductDiscountValue : 0) > 100) {
                    item.ProductDiscountValue = '100';
                }

            }
            else if (type == 'Adjustments') {
                if (item.Adjustments.charAt(0) == '.') {
                    item.Adjustments = ('0' + item.Adjustments);
                }
            }
            else if (type == 'Shipping') {
                if (item.ShippingCharges.charAt(0) == '.') {
                    item.ShippingCharges = ('0' + item.ShippingCharges);
                }
            }
        },
        FetchData: function () {
            debugger
            var vm = this;
            vm.isLoading = true;
            var BillingAddress = {
                BillingContactPerson: '',
                BillingCompanyName: 0,
                BillingAccountAddress: '',
                BillingAccountAddress2: '',
                BillingAccountCity: '',
                BillingCity: '',
                BillingCityList: [],
                BillingZipCode: '',
                BillingZipCodeList: [],
                BillingState: '',
                BillingStateList: [],
                BillingCompanyNameList: [],
                BillingCountry: '',
            };
            var ShippingAddress = {
                ShippingAccountName: '',
                ShippingCompanyName: '',
                ShippingContactPerson: '',
                ShippingAccountAddress: '',
                ShippingAccountAddress2: '',
                ShippingAccountCity: '',
                ShippingCity: '',
                ShippingCityList: [],
                ShippingZipCode: '',
                ShippingZipCodeList: [],
                ShippingState: '',
                ShippingStateList: [],
                ShippingCompanyNameList: [],
                ShippingCountry: '',
            };
            vm.Address = {
                BillingAddress: BillingAddress,
                ShippingAddress: ShippingAddress
            }
            var productSummary = [{
                ProductName: vm.ProductName,
                ProductList: [],
                ProductDescription: '',
                ProductQuantity: vm.Quantity,
                ProductInStock: 0,
                ProductRate: 0,
                ProductTax: 0,
                ProductAmount: 0,
                ProductDiscount: 0,
                ProductDiscountType: 'percent',
                ProductDiscountValue: 0,
                ProductItemTotal: 0,
                PriceBookId: 0,
                toggleDiscount: false,
                toggleTax: false,
                TaxData: [],
                DiscountData: [],
                OnlineLink: ''
            }];
            vm.ProductSummary = {
                SubTotal: 0,
                ShippingCharges: 0,
                Adjustments: 0,
                RoundOff: 0,
                SummaryTotal: 0,
                SummaryData: productSummary
            }
            var Deal_id = vm.reqFromId;
            var AccountD = {};
            var DealD = {};
            const params = `recordId=${vm.$route.params.OrderId}&moduleName=Purchase&subModuleCode=PURCHASE_QUOTATION&langCode=en`;
            vm.quoteID = String(vm.quoteID);
            var quotationType = 1;
            LeadDataService.GetDynamicForm(params).then(async function (response) {

                if (response != null && response.data != null) {
                    vm.isLoading = false;

                    await vm.getMappedVendorList(response.data.data[0].value);

                    vm.FormSchema = vm.$refs.ManageQuoteForm.ConvertCustomFieldIntoDynamicFormObj(response.data.data);
                    vm.FormSchema.forEach((group, gi) => {
                        group.Data.forEach(async (field, fi) => {
                            if (field.name == "account_id") {

                                field.config.options = vm.VendorData;
                                if (field.value != null && field.value != "") {
                                    vm.onChangeVendor(field.value);
                                }

                                // if (field.value != null && field.value != "") {
                                //     var obj = field.config.options.filter(x => x.value == field.value)[0];
                                //     field.value = { label: obj.name, value: obj.value }
                                //  } 
                                //else {
                                //     field.config.options = vm.VendorData;
                                // }
                                //field.config.onSearchChange = vm.onSearchh;
                            }
                            if (field.name == "order_number") {
                                if (vm.quoteID > 0) {
                                    field.value = field.value;
                                } else {
                                    field.value = 'Sales Order number generated automatically.';
                                }
                                field.disabled = true;
                            }
                            if (field.name == 'quotation_type') {
                                field.value = 1;
                                vm.selectedQuotationType = field.value;
                                if (vm.reqFromId != "0") {
                                    field.value = 2;
                                    quotationType = 2;
                                    vm.selectedQuotationType = field.value;
                                }
                            }
                            if (field.name == 'client_id') {
                                field.visibility = false;
                                if (field.value != null && field.value != "") {
                                    var obj = field.config.options.filter(x => x.value == field.value)[0];
                                    field.value = { label: obj.name, value: obj.value }
                                } else {
                                    field.config.options = [];
                                }
                                field.config.onSearchChange = vm.onSearchh;
                            }
                            if (field.name == 'contact_id') {
                                if (field.value != null && field.value != "") {
                                    var obj = field.config.options.filter(x => x.value == field.value)[0];
                                    field.value = { label: obj.name, value: obj.value }
                                } else {
                                    field.config.options = [];
                                }
                                field.config.onSearchChange = vm.onSearchh;
                            }
                            if (field.name == 'deal_id') {
                                field.visibility = false;
                                if (field.value != null && field.value != "") {
                                    var obj = field.config.options.filter(x => x.value == field.value)[0];
                                    field.value = { label: obj.name, value: obj.value }
                                } else {
                                    field.value = '';
                                }
                                if (vm.reqFromId != "0" && quotationType == 2) {
                                    // item.dependent_show_type = 1;
                                }
                            }
                            if (field.name == "deal_id" && vm.quoteID != "0") {
                                vm.dealid = field.value;
                            }
                            if (field.name == "account_id" && vm.quoteID != "0") {
                                vm.accntid = field.value;
                            }
                            if (field.name == "account_id" && vm.quoteID == "0") {
                                AccountD = field;
                            }
                            if (field.name == "deal_id" && vm.quoteID == "0") {
                                DealD = field;
                            }
                            if (field.name == "contact_id" && vm.quoteID != "0") {
                                var newSelect = field.config.options.reduce(function (memo, e1) {
                                    var matches = memo.filter(function (e2) {
                                        return e1.name == e2.name && e1.value == e2.value
                                    })
                                    if (matches.length == 0)
                                        memo.push(e1)
                                    return memo;
                                }, []);
                                field.config.options = [];
                                field.value = [];
                                field.config.options = newSelect;
                                field.value = newSelect;
                            }
                            if (field.name == "attachment_path") {

                                field.showLabel = true;
                                field.config =
                                {
                                    maxSize: 5,
                                    onDeleteSelectedFiles: vm.onDeleteSelectedFiles,
                                    accept: [{
                                        fileType: 'jpg',
                                        iconClass: 'fa-file-image-o'
                                    },
                                    {
                                        fileType: 'jpeg',
                                        iconClass: 'fa-file-image-o'
                                    },
                                    {
                                        fileType: 'png',
                                        iconClass: 'fa-file-image-o'
                                    },

                                    ],
                                    showAddIcon: false,
                                    onAddButtonClick: '',
                                    multiple: false,
                                    showSelectedFiles: [],
                                }
                                if (field.value != null && field.value != "") {
                                    field.visibility = true;

                                    let url = new URL(field.value);
                                    let filePath = url.pathname.startsWith('/') ? url.pathname : '/' + url.pathname;
                                    let attachmentPath = filePath.replace(/^\/+/, '');
                                    let attachmentName = attachmentPath.split('/').pop();
                                    var attachmentData = { attachmentName: attachmentName, attachmentPath: attachmentPath };
                                    if (attachmentPath != null && attachmentName != null) {
                                        field.config.showSelectedFiles.push(attachmentData);
                                        // vm.FormSchema[3].Data[0].config.showSelectedFiles.push(attachmentData);
                                    }
                                    //  var Attachment = {
                                    //     name: 'Mohit',
                                    //     path: field.values
                                    //   }

                                    //   field.config.showSelectedFiles.push(Attachment);
                                }
                                else {
                                    field.visibility = false;
                                }

                            }
                            if (field.name == "ref_date") {
                                const today = new Date();
                                const yyyy = today.getFullYear();
                                const mm = String(today.getMonth() + 1).padStart(2, '0');
                                const dd = String(today.getDate()).padStart(2, '0');
                                field.value = `${yyyy}-${mm}-${dd}`;
