        SaveAsDraft(values) {

            var vm = this;
            var chkSummaryData = "";
            vm.submited = true;
            var quotationType = 0;
            var Accid = 0;
            var CustomFieldArray = vm.$refs.ManageQuoteForm.ConvertDynamicFormObjToCustomFieldObj(vm.FormSchema);
            CustomFieldArray.forEach((x) => {
                if (x.field_name == 'created_by') {
                    x.field_value = vm.userId;
                }
                if (x.field_name == 'modified_by') {
                    x.field_value = vm.userId;
                }
                if (x.field_name == 'company_id') {
                    x.field_value = vm.companyId;
                }
                if (x.field_name == 'order_id') {
                    x.field_value = vm.quoteID;
                }
                if (x.field_name == 'quotation_type') {
                    quotationType = x.field_value;
                }
                // if (x.field_name == "account_id") {
                // //     Accid = x.value;
                // }
                if (x.field_name == "account_id") {
                    if (!vm.isBlank(x.field_value)) {
                        x.field_value = x.field_value.value;
                    }
                }
                if (x.field_name == "client_id") {
                    if (!vm.isBlank(x.field_value)) {
                        //  x.field_value = x.field_value.value;
                        x.field_value = x.field_value?.value === undefined ? x.field_value : x.field_value.value;
                    }
                }
                if (x.field_name == "contact_id") {
                    if (!vm.isBlank(x.field_value)) {
                        x.field_value = x.field_value.value;
                        Accid = x.field_value;
                    }
                }

            });

            var productSummaryData = [];
            $.each(vm.ProductSummary.SummaryData, function (key, item) {
                var projectId = 0;
                if (quotationType == 2) {
                    if (Array.isArray(item.ProductName)) {
                        try {
                            projectId = (typeof item.ProductName[0] === 'object' && item.ProductName[0] !== null) ? item.ProductName[0].value : item.ProductName[0];
                        } catch (ex) {
                            projectId = item.ProductName[0];
                        }
                    }
                    else {
                        projectId = item.ProductName == null ? '' : item.ProductName.value;
                    }
                } else {
                    projectId = item.ProductName;
                }

                if (typeof (projectId) != 'undefined' || item.ProductName != '') {
                    if (projectId.length > 0 || projectId != 0) {
                        var dataObject = {
                            ProductName: projectId,
                            ProductDescription: item.ProductDescription,
                            ProductQuantity: item.ProductQuantity,
                            ProductRate: item.ProductRate,
                            ProductTax: item.ProductTax,
                            ProductAmount: item.ProductAmount,
                            ProductDiscount: item.ProductDiscount,
                            ProductDiscountType: item.ProductDiscountType,
                            ProductDiscountValue: item.ProductDiscountValue,
                            ProductItemTotal: item.ProductItemTotal,
                            PriceBookId: item.PriceBookId,
                            IsTaxApplicable: (item.TaxData != null && item.TaxData.length > 0 ? 1 : 0),
                            TaxData: item.TaxData,
                        };
                        productSummaryData.push(dataObject);
                    }
                }

            });


            if (productSummaryData.length == 0) {
                chkSummaryData = "no";
            }
            var productSummary = {
                SubTotal: vm.ProductSummary.SubTotal,
                ShippingCharges: (vm.ProductSummary.ShippingCharges != '') ? vm.ProductSummary.ShippingCharges : '0',
                Adjustments: (vm.ProductSummary.Adjustments != '') ? vm.ProductSummary.Adjustments : '0',
                SummaryTotal: vm.ProductSummary.SummaryTotal,
                SummaryData: productSummaryData
            }
            if (vm.ProductSummary.SummaryTotal < 0) {
                vm.ShowAlert("Total amount cannot be in minus.", "warning", true, vm.$t("Alert"));
                vm.submited = false;

                return false;
            }

            var billingAddress = {
                BillingContactPerson: vm.Address.BillingAddress.BillingContactPerson,
                BillingCompanyName: vm.Address.BillingAddress.BillingCompanyName,
                BillingAccountAddress: vm.Address.BillingAddress.BillingAccountAddress,
                BillingCity: vm.Address.BillingAddress.BillingCity,
                BillingZipCode: vm.Address.BillingAddress.BillingZipCode,
                BillingState: vm.Address.BillingAddress.BillingState,
                BillingCountry: vm.Address.BillingAddress.BillingCountry.toString(),
                BillingAccountAddress2: vm.Address.BillingAddress.BillingAccountAddress2,
                BillingAccountCity: vm.Address.BillingAddress.BillingAccountCity
            };

            var shippingAddress = {
                ShippingContactPerson: vm.Address.ShippingAddress.ShippingContactPerson,
                ShippingCompanyName: vm.Address.ShippingAddress.ShippingCompanyName,
                ShippingAccountAddress: vm.Address.ShippingAddress.ShippingAccountAddress,
                ShippingCity: vm.Address.ShippingAddress.ShippingCity,
                ShippingZipCode: vm.Address.ShippingAddress.ShippingZipCode,
                ShippingState: vm.Address.ShippingAddress.ShippingState,
                ShippingCountry: vm.Address.ShippingAddress.ShippingCountry,
                ShippingAccountAddress2: vm.Address.ShippingAddress.ShippingAccountAddress2,
                ShippingAccountCity: vm.Address.ShippingAddress.ShippingAccountCity
            };
            var address = {
                BillingAddress: billingAddress,
                ShippingAddress: shippingAddress
            }
            var statusType = 'D';
            var status = {
                Status: values
            }
            var subModuleCode = {
                SubModuleCode: 'PURCHASE_QUOTATION',
            }
            var postJSON = {
                data: CustomFieldArray,
                address: address,
                productSummary: productSummary,
                status: status,
                subModuleCode: subModuleCode,
                RequisitionId: vm.RequisitionId,
                filePath: vm.filePath,
                ModuleName: 'Purchase'
            };
            if (chkSummaryData.length >= 0 && Accid != "") {
                var objectPostString = JSON.stringify(postJSON);
                LeadDataService.SaveOrder(objectPostString).then(response => {
                    if (response.data[0].Code == "1" || response.data[0].Code == "0") {
                        var msg = "";
                        if (vm.quoteID > 0) {
                            if (statusType == "D") {
                                vm.ShowAlert(vm.$t('DraftSuccess', [vm.$t('Quotation')]), "success", true, vm.$t("Alert"));
                            }
                            else {
                                vm.ShowAlert(vm.$t('UpdatedSuccess', [vm.$t('Quotation')]), "success", true, vm.$t("Alert"));
                            }
                        }
                        else {
                            if (statusType == "D") {
                                vm.ShowAlert(vm.$t('DraftSuccess', [vm.$t('Quotation')]), "success", true, vm.$t("Alert"));
                            }
                            else {
                                msg = vm.$t("SubmitSuccess") + vm.$t("Quotation") + String(vm.$t("Generated")).toLowerCase() + response.data[0].Name;
                                vm.ShowAlert(msg, "success", true, vm.$t("Alert"));
                            }
                        }

                    }
                    else {
                        vm.ShowAlert(vm.$t('AddedError', [vm.$t('Quotation')]), "failure", true, vm.$t("Alert"));
                    }
                    vm.submited = false;
                    vm.onCancel();
                });
            }
            else {
                vm.submited = false;
                vm.ShowAlert("Please Select Account Name", "warning", true, vm.$t("Alert"));
            }
        },
