        FetchDefaultUserAddress: function () {
            debugger

            var VueObj = this;
            VueObj.isLoading = true;

            var params = `RequisitionId=${VueObj.RequisitionId}`;

            LeadDataService.DefaultUserAddress(params).then(function (response) {
                VueObj.isLoading = false;

                if (response.data != null) {
                    VueObj.DefaultUserAddress = response.data.Data;

                    VueObj.RequisitionLocationId = response.data.LocationId;


                    const matchedAddress = VueObj.DefaultUserAddress.find(function (item) {
                        return item.company_location_id === VueObj.RequisitionLocationId;
                    });


                    // Convert address to dropdown list
                    const addressList = VueObj.DefaultUserAddress.map(function (item, index) {
                        const address = [item.user_address_1, item.user_address_2]
                            .filter(Boolean)
                            .join(' ')
                            .trim();

                        const name = `${item.location_name || 'Unknown'} (${address || 'No Address'})`;

                        return {
                            name: name,
                            value: item.company_location_id
                        };
                    });

                    const shippingAddressList = [{
                        name: "Add Manually",
                        value: 0
                    }, ...addressList];

                    VueObj.BillingAddressList = addressList;
                    VueObj.ShippingAddressList = shippingAddressList;

                    if (VueObj.$route.params.OrderId == 0) {
                        VueObj.Address.BillingAddress = {
                            BillingCompanyNameList: addressList,
                            BillingCompanyName: VueObj.RequisitionLocationId || null, // initial selection
                            BillingContactPerson: '',
                            BillingAccountAddress: matchedAddress.user_address_1,
                            BillingAccountAddress2: matchedAddress.user_address_2,
                            BillingAccountCity: matchedAddress.user_city,
                            BillingCity: matchedAddress.user_city,
                            BillingZipCode: matchedAddress.user_zipcode,
                            BillingState: matchedAddress.user_state,
                            BillingCountry: matchedAddress.country_id
                        };



                        VueObj.Address.ShippingAddress = {
                            ShippingCompanyNameList: shippingAddressList,
                            ShippingCompanyName: null, // initial selection
                            ShippingContactPerson: '',
                            ShippingAccountAddress: '',
                            ShippingAccountAddress2: '',
                            ShippingAccountCity: '',
                            ShippingCity: '',
                            ShippingZipCode: '',
                            ShippingState: '',
                            ShippingCountry: '',
                            ShippingStateList: ''
                        };
                    }


                }
            });
        },

        onBillingAddressChange: function () {


            const selectedCompanyId = this.Address.BillingAddress.BillingCompanyName;

            if (selectedCompanyId !== null) {
                // Find the matching object by company_location_id
                const selected = this.DefaultUserAddress.find(addr => addr.company_location_id === selectedCompanyId);

                if (selected) {
                    this.Address.BillingAddress.BillingContactPerson = selected.contact_name || "";
                    this.Address.BillingAddress.BillingAccountAddress = selected.user_address_1 || "";
                    this.Address.BillingAddress.BillingAccountAddress2 = selected.user_address_2 || "";
                    this.Address.BillingAddress.BillingAccountCity = selected.user_city || "";
                    this.Address.BillingAddress.BillingCity = selected.country_name || "";
                    this.Address.BillingAddress.BillingZipCode = selected.user_zipcode || "";
                    this.Address.BillingAddress.BillingState = selected.user_state || "";
                    this.Address.BillingAddress.BillingCountry = selected.country_id || "";
                }
            }
        },
        onShippingAddressChange: function () {


            const selectedCompanyId = this.Address.ShippingAddress.ShippingCompanyName;

            if (selectedCompanyId == 0) {
                this.IsManually = true;
            }

            if (selectedCompanyId !== null && selectedCompanyId != 0 && selectedCompanyId != undefined) {
                // Find the matching object by company_location_id

                this.IsManually = false;
                const selected = this.DefaultUserAddress.find(addr => addr.company_location_id === selectedCompanyId);

                if (selected) {
                    this.Address.ShippingAddress.ShippingContactPerson = selected.contact_name || "";
                    this.Address.ShippingAddress.ShippingAccountAddress = selected.user_address_1 || "";
                    this.Address.ShippingAddress.ShippingAccountAddress2 = selected.user_address_2 || "";
                    this.Address.ShippingAddress.ShippingAccountCity = selected.user_city || "";
                    this.Address.ShippingAddress.ShippingCity = selected.country_name || "";
                    this.Address.ShippingAddress.ShippingZipCode = selected.user_zipcode || "";
                    this.Address.ShippingAddress.ShippingState = selected.user_state || "";
                    this.Address.ShippingAddress.ShippingCountry = selected.country_id || "";
                }
            }
        },
        async getMappedVendorList(OrderId) {

            this.isLoading = true;
            const params = `Requestion_id=${this.RequisitionId}&Order_id=${OrderId}`;
            try {
                const response = await LeadDataService.VendorListingBasedOnQuoatation(params);
                if (response.data && response.data.length > 0) {
                    this.VendorsDetails = response.data;
                    const mappedVendors = response.data.map(ele => ({
                        name: ele.Vendor_Name,
                        value: ele.Vendor_Id
                    }));
                    this.VendorData = [...mappedVendors];
                } else {
                    this.VendorData = [];
                }
            } catch (error) {
                console.error("Error fetching vendor data:", error);
            } finally {
                this.isLoading = false;
            }
        },
        async UploadFile(evt) {

            try {
                var vm = this;
                let file = [];
                for (var i = 0; i < evt.length; i++) {
                    file = evt[i];
                }
                const formData = new FormData();
                formData.append('file', file);
                await LeadDataService.UploadImageFile(formData).then(response => {
                    if (response.data.status == "1") {
                        vm.filePath = response.data.filePath;
                    }
                    else {
                        vm.filePath = '';
                    }
                }).catch(err => {
                    console.log(err);
                })
            }
            catch (ex) {
                console.error("Error processing attachments:", ex);
            }


        },
        async UpdateRequisition(id) {

            var vm = this;
            vm.isLoading = true;
            try {
                const params = `id=${id}`;
                const response = await LeadDataService.UpdateRequisition(params);
                if (response.data) {
                    vm.ProductName = response.data.productName;
                    vm.Quantity = response.data.Quantity;
                }
            } catch (error) {
                console.error("Error updating requisition:", error);
            } finally {
                vm.isLoading = false;
            }
        }




    }
